import { MeshStandardNodeMaterial } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, PointLight } = ctx.THREE;

  // Resolve config colors
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const mainGroup = new Group();

  // Create local interactive container
  const cardContainer = new Group();
  mainGroup.add(cardContainer);

  // --- BACKGROUND FLAT GRADIENT STAGE (Grounded Backdrop) ---
  const backdropGeo = new PlaneGeometry(8, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.1,
    depthWrite: false
  });
  // Vertical gradient from ink to surface color
  backdropMat.colorNode = mix(
    vec3(0.043, 0.043, 0.062), // Dark surface
    vec3(0.086, 0.086, 0.113), // Ink
    uv().y
  );
  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -0.6);
  mainGroup.add(backdropMesh);

  // --- LOCAL LIGHTS (Product Shot Quality) ---
  // Key Light
  const keyLight = new PointLight(colors.paper, 1.2, 8);
  keyLight.position.set(-1.5, 2, 2.5);
  mainGroup.add(keyLight);

  // local Rim/Accent Light on the edge
  const rimLight = new PointLight(colors.accent, 1.5, 6);
  rimLight.position.set(2, -1.5, 1.5);
  mainGroup.add(rimLight);

  // --- MAIN CARD PANEL (Machined Surface) ---
  const width = 2.4;
  const height = 1.6;
  const depth = 0.06;

  const panelGeo = new BoxGeometry(width, height, depth);
  const panelMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.22,
    clearcoatRoughness: 0.3
  });
  const panelMesh = new Mesh(panelGeo, panelMat);
  cardContainer.add(panelMesh);

  // --- ACCENT RED FRAME BACKING ---
  const frameGeo = new BoxGeometry(width + 0.04, height + 0.04, depth - 0.01);
  const frameMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 0.3,
    roughness: 0.2,
    metalness: 0.8
  });
  const frameMesh = new Mesh(frameGeo, frameMat);
  frameMesh.position.z = -0.01;
  cardContainer.add(frameMesh);

  // --- IMAGE PLANE ---
  const imgWidth = width - 0.16;
  const imgHeight = height - 0.36;
  const imgGeo = new PlaneGeometry(imgWidth, imgHeight);
  const imgMat = new MeshStandardNodeMaterial({
    roughness: 0.4,
    metalness: 0.1,
    transparent: true
  });

  const imgMesh = new Mesh(imgGeo, imgMat);
  imgMesh.position.set(0, 0.1, depth / 2 + 0.005);
  cardContainer.add(imgMesh);

  // Load Image Texture
  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/cta-hero-isolated.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    imgMat.map = tex;
    imgMat.needsUpdate = true;
  });

  // --- CAPTION / MONO LABELS ---
  const labelGroup = new Group();
  labelGroup.position.set(-imgWidth / 2, -height / 2 + 0.16, depth / 2 + 0.01);
  cardContainer.add(labelGroup);

  const primaryLabel = ctx.fontAtlas.createText('N° 01 / EDITORIAL', {
    fontSize: 22,
    color: colors.paper,
    align: 'left'
  });
  primaryLabel.position.set(0, 0, 0);
  labelGroup.add(primaryLabel);

  const subLabel = ctx.fontAtlas.createText('VIEW JOURNAL ARCHIVE', {
    fontSize: 14,
    color: colors.accent,
    align: 'left'
  });
  subLabel.position.set(0, -0.08, 0);
  labelGroup.add(subLabel);

  // --- INTERACTIONS & TIMELINES ---
  let isHovered = false;
  const hoverTl = gsap.timeline({ paused: true });

  // Weighted-settle & rise-in micro-animation
  hoverTl.to(cardContainer.position, {
    y: 0.15,
    z: 0.16,
    duration: 0.6,
    ease: 'power3.out'
  });
  hoverTl.to(cardContainer.rotation, {
    x: 0.04,
    y: -0.04,
    duration: 0.6,
    ease: 'power3.out'
  }, '<');
  hoverTl.to(frameMat, {
    emissiveIntensity: 1.2,
    duration: 0.4
  }, '<');

  const onPointerOver = () => {
    isHovered = true;
    hoverTl.play();
  };

  const onPointerOut = () => {
    isHovered = false;
    hoverTl.reverse();
  };

  const onPointerDown = () => {
    gsap.to(cardContainer.scale, {
      x: 0.96,
      y: 0.96,
      z: 0.96,
      duration: 0.12,
      ease: 'back.out(1.7)'
    });
  };

  const onPointerUp = () => {
    gsap.to(cardContainer.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.3,
      ease: 'power4.out'
    });
    ctx.emit('hub-journal.select', { id: config.id ?? 'journal-cta' });
  };

  // Bind WebGL system interactions
  mainGroup.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp
  };

  // Apply generic cinematic primitives (if passed down dynamically)
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        const instance = ctx.primitives[prim.name](cardContainer, prim.params);
        activePrimitives.push(instance);
      }
    }
  }

  // --- MEMORY CLEANUP ---
  mainGroup.userData.cleanup = () => {
    hoverTl.kill();
    gsap.killTweensOf(cardContainer.position);
    gsap.killTweensOf(cardContainer.rotation);
    gsap.killTweensOf(cardContainer.scale);
    gsap.killTweensOf(frameMat);

    // Dispose local primitives
    activePrimitives.forEach((p) => p?.cleanup?.());

    // Deep geometry and material disposal
    backdropGeo.dispose();
    backdropMat.dispose();
    panelGeo.dispose();
    panelMat.dispose();
    frameGeo.dispose();
    frameMat.dispose();
    imgGeo.dispose();
    imgMat.dispose();
    if (imgMat.map) imgMat.map.dispose();
  };

  return mainGroup;
}
